using Microsoft.AspNetCore.Identity;

namespace Auth.Entities;

/// <summary>
/// Auth service user: ASP.NET Identity user with a version-7 <see cref="Guid"/>
/// key (time-ordered, generated by the application), the login in
/// <see cref="IdentityUser.UserName"/> and a PBKDF2 <see cref="IdentityUser.PasswordHash"/>
/// (ADR 0018 — PBKDF2, not the monolith's SHA-256+salt), plus the profile
/// fields the SPA needs (<c>fullName</c>, <c>birthDate</c>).
///
/// The key is a Guid (not an integer) on purpose (ADR 0018, step 4.3a.1):
/// the JWT <c>sub</c> is this id as a canonical lower-case string, and the
/// monolith stores file owners as strings — a numeric id space would collide
/// with the legacy monolith owners (a numeric Auth id '4' would "own" the
/// legacy files stored with user_id '4'), while a Guid can never be confused
/// with a decimal string.
/// </summary>
public class AuthUser : IdentityUser<Guid>
{
    /// <summary>
    /// Version-7 Guid (time-ordered, <c>Guid.CreateVersion7</c> — .NET 9+):
    /// generated here so <c>UserManager.CreateAsync</c> keeps it (it only
    /// substitutes the key when it is still <c>default</c>).
    /// </summary>
    public override Guid Id { get; set; } = Guid.CreateVersion7();

    public string? FullName { get; set; }

    public DateOnly? BirthDate { get; set; }
}
